import os
from google.cloud import documentai_v1 as documentai

def extract_invoice_data(document_bytes):
    """
    Extract vendor, date, total, and line-item fields from an invoice using Google Document AI.

    Args:
        document_bytes (bytes): Raw bytes of the PDF or image document.

    Returns:
        dict: Structured data containing vendor, date, total, and line items.
    """
    project_id = os.getenv("GOOGLE_PROJECT_ID")
    location = "us"  # Format: us, eu, etc.
    processor_id = os.getenv("DOCUMENTAI_PROCESSOR_ID")

    client = documentai.DocumentProcessorServiceClient(client_options={
        'api_endpoint': f'{location}-documentai.googleapis.com'
    })

    raw_document = documentai.RawDocument(content=document_bytes, mime_type="application/pdf")
    request = documentai.ProcessRequest(name=f"projects/{project_id}/locations/{location}/processors/{processor_id}", raw_document=raw_document)

    result = client.process(request=request)
    document = result.document

    extracted_data = {
        "vendor": None,
        "date": None,
        "total": None,
        "line_items": []
    }

    for entity in document.entities:
        if entity.type_ == "ORG_NAME":
            extracted_data["vendor"] = entity.text_access
        elif entity.type_ == "DATE":
            extracted_data["date"] = entity.text_access
        elif entity.type_ == "TOTAL_AMOUNT":
            extracted_data["total"] = entity.text_access

    for table in document.tables:
        for row in table.rows:
            line_item = {}
            for i, cell in enumerate(row.cells):
                key_text = cell.text_access.strip().lower()
                if "description" in key_text or "item" in key_text:
                    line_item["description"] = cell.text_access
                elif "quantity" in key_text:
                    line_item["quantity"] = cell.text_access
                elif "price" in key_text or "amount" in key_text:
                    line_item["price"] = cell.text_access
            if line_item:
                extracted_data["line_items"].append(line_item)

    return extracted_data
